def weights(y, prior=0.02, population=100000):
    y = np.asarray(y)
    return np.where(y == 1, population * prior / y.sum(), population * (1 - prior) / (len(y) - y.sum()))

def cutoff(score, weight, share):
    order = np.argsort(-np.asarray(score), kind='stable')
    cumulative = np.cumsum(np.asarray(weight)[order])
    return float(np.asarray(score)[order[min(np.searchsorted(cumulative, np.sum(weight) * share), len(order) - 1)]])

def scores(frame, prior=0.02, proxy=None):
    p = frame.p_s.to_numpy()
    value = frame.value.to_numpy() if proxy is None else np.asarray(proxy)
    pd_ = shift(p, prior)
    return {'risk': pd_, 'value': value, 'sample_rv': p * value, 'bayes': pd_ * value, 'profit_gate': pd_ * value}

def fit_thresholds(frame, prior=0.02, fraction=0.1, cost=1.0, proxy=None):
    w = weights(frame.y.to_numpy(), prior)
    thresholds = {name: cutoff(score, w, fraction) for name, score in scores(frame, prior, proxy).items()}
    thresholds['profit_gate'] = max(thresholds['profit_gate'], cost / (0.2 * 6 * 0.6))
    return thresholds
